import numpy as np

class SuperconductorModel:
    def __init__(self, tc=92.0): # Ejemplo YBCO
        self.Tc = tc # Temperatura crítica en Kelvin

    def london_penetration_depth(self, t):
        """λ(T) = λ0 / sqrt(1 - (T/Tc)⁴)"""
        lambda0 = 140 # nm
        if t >= self.Tc:
            return np.inf
        return lambda0 / np.sqrt(1 - (t / self.Tc)**4)

    def superconducting_gap(self, t):
        """BCS Theory approximation for Δ(T)"""
        if t >= self.Tc:
            return 0.0
        delta0 = 1.76 * 8.617e-5 * self.Tc # k_B * Tc
        return delta0 * np.sqrt(1 - t / self.Tc)

